import React, { useEffect, useState } from "react";
import Button from '@mui/material/Button';
import TextField from '@mui/material/TextField';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import { FormHelperText, GlobalStyles } from "@mui/material";
import Rating from '@mui/material/Rating';
import StarRating from "./StarRating";
import { useAuth } from "./AuthContext";

//This component allows user to edit an existing review.
function EditReviewDialogue({ Review, editReview }) {

    //Hook to control open and closing of dialogue
    const [open, setOpen] = useState(false);
    //Set error state
    const [error, setError] = useState(false);

    //Opens dialogue
    const handleClickOpen = () => {
        setOpen(true);
        };
    
    //Closes dialogue
    const handleClose = () => {
    setOpen(false);
    };

    //Variable to store the customer's rating
    let starRating = 5;
    //This function handles rating changes
    function handleRating(rating) {
        starRating = rating;
    }

    //Set date (DD/MM/YYYY)
    function getDate() {
        var today = new Date();
        var dd = String(today.getDate()).padStart(2, '0');
        var mm = String(today.getMonth() + 1).padStart(2, '0'); //January is 0!
        var yyyy = today.getFullYear();
  
        today = mm + '/' + dd + '/' + yyyy;
        return today;
      }

    return (
        <React.Fragment>
            <Button onClick={handleClickOpen}>Edit your review</Button>
            <Dialog
            open={open}
            onClose={handleClose}
            PaperProps={{
              component: 'form',
              onSubmit: (event) => {
                event.preventDefault();
                event.stopPropagation();
                const data = new FormData(event.currentTarget);
                const formJson = Object.fromEntries(data.entries());
                const review = formJson.review;
                const name = formJson.name;
                const date = getDate();
                //Store the new review in local storage
                if (error) {
                  alert("Review must be between 0 - 100 words");
                }
                else {
                  editReview(Review, {name: name, date: date, rating: starRating, review: review, userEmail: Review.email});
                  handleClose();
                }
              },
            }}
          >
            <DialogTitle>Edit review</DialogTitle>
            <DialogContent>
              {/* Accepts a callback to change rating each time it changes in the child */}
              <StarRating handleRating={handleRating} />
              <br />
              <TextField 
                autoFocus
                required
                defaultValue={Review.name}
                margin="dense"
                id="name"
                name="name"
                label="Name"
                fullWidth
                variant="standard"
                multiline="true"
              />
              <TextField
                error={error}
                autoFocus
                required
                defaultValue={Review.review}
                margin="dense"
                id="review"
                name="review"
                helperText="Review must be between 0 - 100 words"
                label="Your review"
                fullWidth
                variant="standard"
                multiline="true"
                rows={5}
                onChange={(e) => {
                   if (e.target.value.split(' ').length > 100) {
                    setError(true);
                    }
                    else {
                      setError(false);
                    }
                }}
              />
            </DialogContent>
            {/* Cancel and close buttons */}
            <DialogActions>
              <Button onClick={handleClose}>Cancel</Button>
              <Button type="submit">Finish</Button>
            </DialogActions>
          </Dialog>
        </React.Fragment>
    );
};

export default EditReviewDialogue;
