import React, { useEffect, useState } from "react";
import Button from '@mui/material/Button';
import TextField from '@mui/material/TextField';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import { FormHelperText, GlobalStyles } from "@mui/material";
import Rating from '@mui/material/Rating';
import StarRating from "./StarRating";
import EditReviewDialogue from "./EditReviewDialogue";
import { useAuth } from "./AuthContext";

//Component defines a dialogue box used to add a review
//Tutorial Used: https://mui.com/material-ui/react-dialog/

//For input with zero styling use:
//https://mui.com/base-ui/react-input/

//Try using modal with this: https://dev.to/franciscomendes10866/how-to-create-a-modal-in-react-3coc
function ReviewDialogue() {

    // Use the useAuth hook to get the login status
    const { isUserLoggedIn } = useAuth(); 

    //User should only be able to edit/delete reviews written by themselves
    //Retrieve the email of logged in user and check this matches email of review
    let loggedInEmail = localStorage.getItem("loggedInEmail");
    let profiles = JSON.parse(localStorage.getItem("profiles"));
    if (profiles !== null) {
      const userProfile = profiles.filter(obj => obj.email === loggedInEmail);
    }

    //Set error state
    const [error, setError] = useState(false);
    //Hook to handle storage of reviews
    const [reviews, setReviews] = useState([]);

    //Initialise local storage with a review array
    if (localStorage.getItem("reviews") === null) {
      localStorage.setItem("reviews", JSON.stringify([]));
    }

    //Hook to control open and closing of dialogue
    const [open, setOpen] = useState(false);

    //Opens dialogue
    const handleClickOpen = () => {
      //Check user is logged in before adding a review
      if (!isUserLoggedIn) {
        alert("Please sign in to add a review.");
      }
      else {
        setOpen(true);
      }
    };

    //Closes dialogue
    const handleClose = () => {
      setOpen(false);
    };

    //Variable to store the customer's rating
    let starRating = 5;
    //This function handles rating changes
    function handleRating(rating) {
      starRating = rating;
    }

    //Set date (DD/MM/YYYY)
    function getDate() {
      var today = new Date();
      var dd = String(today.getDate()).padStart(2, '0');
      var mm = String(today.getMonth() + 1).padStart(2, '0'); //January is 0!
      var yyyy = today.getFullYear();

      today = mm + '/' + dd + '/' + yyyy;
      return today;
    }

    //Function to add review into local storage
    function addReview(review) {
      let reviews = JSON.parse(localStorage.getItem("reviews"));
      reviews = [...reviews, review];
      localStorage.setItem("reviews", JSON.stringify(reviews));
      setReviews(reviews);
      alert("Your review has been added!");
    }

    //Function to remove a review
    function removeReview(reviewToDelete) {
        setReviews(reviews => {
          reviews = reviews.filter(obj => obj.review !== reviewToDelete);
          localStorage.setItem("reviews", JSON.stringify(reviews));
          return reviews;
        });
    }

    //Function to add review into local storage
    function editReview(oldReview, newReview) {
      let reviews = JSON.parse(localStorage.getItem("reviews"));
      const pos = reviews.map(obj => obj.review).indexOf(oldReview.review);
      // alert(pos);
      reviews[pos].name = newReview.name;
      reviews[pos].review = newReview.review;
      reviews[pos].rating = newReview.rating;
      reviews[pos].date = newReview.date;
      setReviews(reviews);
      localStorage.setItem("reviews", JSON.stringify(reviews));
      alert("Your review has been updated!");
    }

    return (
        <React.Fragment>
          <Button variant="outlined" onClick={handleClickOpen}>
            Add review
          </Button>
          <Dialog
            open={open}
            onClose={handleClose}
            PaperProps={{
              component: 'form',
              onSubmit: (event) => {
                event.preventDefault();
                const formData = new FormData(event.currentTarget);
                const formJson = Object.fromEntries(formData.entries());
                const review = formJson.review;
                const name = formJson.name;
                const date = getDate();
                //Store the new review in local storage
                if (error) {
                  alert("Review must be between 0 - 100 words");
                }
                else {
                  addReview({name: name, date: date, rating: starRating, review: review, userEmail: loggedInEmail});
                }
              },
            }}
          >
            <DialogTitle>Add a review</DialogTitle>
            <DialogContent>
              {/* Accepts a callback to change rating each time it changes in the child */}
              <StarRating handleRating={handleRating} />
              <br />
              <TextField 
                autoFocus
                required
                margin="dense"
                id="name"
                name="name"
                label="Name"
                fullWidth
                variant="standard"
                multiline="true"
              />
              <TextField
                error={error}
                autoFocus
                required
                margin="dense"
                id="review"
                name="review"
                helperText="Review must be between 0 - 100 words"
                label="Your review"
                fullWidth
                variant="standard"
                multiline="true"
                rows={5}
                onChange={(e) => {
                   if (e.target.value.split(' ').length > 100) {
                    setError(true);
                    }
                    else {
                      setError(false);
                    }
                }}
              />
            </DialogContent>
            {/* Display existing customer reviews here */}
            <DialogTitle>Customer Reviews</DialogTitle>
            <DialogContent>
              {( reviews && reviews.length > 0) ? (reviews.map((review, index) => 
                <DialogContent>
                  {review.name}<br />
                  {review.date}<br />
                  <Rating name="read-only" value={review.rating} readOnly /><br />
                  {review.review}
                  {/* Delete/Edit options exclusive to the logged in user are set here*/}
                  {(loggedInEmail === review.userEmail) ? 
                    (<DialogContent>
                      <Button onClick={() => removeReview(review.review)}>Delete</Button>
                      <EditReviewDialogue Review={review} editReview={editReview}/>
                    </DialogContent>)
                    :
                    (<DialogContent />)
                  }
              </DialogContent>
              )) 
              : 
              (<DialogContent>No reviews</DialogContent>)}
            </DialogContent>
            <DialogActions>
              <Button onClick={handleClose}>Cancel</Button>
              <Button type="submit">Post</Button>
            </DialogActions>
          </Dialog>
        </React.Fragment>
      );
}

export default ReviewDialogue;